ox=\"true\" image_hover=\"overlay-remove\" depth=\"3\" depth_hover=\"5\" animate=\"fadeInLeft\"]\n\n\n[/col]\n[col span=\"3\" span__sm=\"6\"]\n\n[ux_image id=\"72\" height=\"75%\" lightbox=\"true\" image_hover=\"overlay-remove\" depth=\"3\" depth_hover=\"5\" animate=\"fadeInLeft\"]\n\n\n[/col]\n[col span=\"3\" span__sm=\"6\"]\n\n[ux_image id=\"72\" height=\"75%\" lightbox=\"true\" caption=\"true\" image_hover=\"overlay-remove\" depth=\"3\" depth_hover=\"5\" animate=\"fadeInLeft\"]\n\n\n[/col]\n[col span=\"3\" span__sm=\"6\"]\n\n[ux_image id=\"72\" height=\"75%\" lightbox=\"true\" caption=\"true\" image_hover=\"overlay-remove\" depth=\"3\" depth_hover=\"5\" animate=\"fadeInLeft\"]\n\n\n[/col]\n[col span__sm=\"12\" align=\"center\"]\n\n[title style=\"center\" text=\"Images with Caption\" size=\"undefined\"]\n\n[row_inner]\n\n[col_inner span=\"4\" span__sm=\"12\"]\n\n[ux_image id=\"72\" height=\"75%\" caption=\"true\" image_hover=\"overlay-remove\" depth=\"3\" depth_hover=\"5\" animate=\"fadeInLeft\"]\n\n\n[/col_inner]\n[col_inner span=\"4\" span__sm=\"12\"]\n\n[ux_image id=\"72\" height=\"75%\" caption=\"true\" image_hover=\"overlay-remove\" depth=\"3\" depth_hover=\"5\" animate=\"fadeInLeft\"]\n\n\n[/col_inner]\n[col_inner span=\"4\" span__sm=\"12\"]\n\n[ux_image id=\"72\" height=\"75%\" caption=\"true\" image_hover=\"overlay-remove\" depth=\"3\" depth_hover=\"5\" animate=\"fadeInLeft\"]\n\n\n[/col_inner]\n\n[/row_inner]\n\n[/col]\n\n[/row]', 'Images', '', 'inherit', 'closed', 'closed', '', '113-revision-v1', '', '', '2025-12-13 16:28:08', '2025-12-13 16:28:08', '', 113, 'http://localhost:8088/artprintstudio/?p=183', 0, 'revision', '', 0),
